 for module in re.findall(r'^import\s+([A-Za-z0-9_.]+)\s*$',source.read_text(),re.M):
  rel=module.replace('.','/')+'.olean'
  resolved=next((Path(d)/rel for d in env['LEAN_PATH'].split(':') if (Path(d)/rel).is_file()),None)
  need(resolved is not None,'unresolved direct import '+module)
  path=str(resolved.resolve());digest=sha(resolved)
  need(path in pinned and digest==pinned[path],'unlisted or mismatched direct import '+module+' '+path)
  result.append({'module':module,'path':path,'sha256':digest})
 return result
